struct ListNode {int val;struct ListNode *next;};
struct ListNode *merge_k_lists(struct ListNode *lists[],int count){struct ListNode dummy;struct ListNode *tail;int best;int i;dummy.next=0;tail=&dummy;while(1){best=-1;for(i=0;i<count;i=i+1){if(lists[i]!=0&&(best<0||lists[i]->val<lists[best]->val))best=i;}if(best<0)break;tail->next=lists[best];lists[best]=lists[best]->next;tail=tail->next;}tail->next=0;return dummy.next;}
int main(void){struct ListNode a[3];struct ListNode b[3];struct ListNode c[2];struct ListNode *lists[3];struct ListNode *r;int e[8]={1,1,2,3,4,4,5,6};int i;int av[3]={1,4,5};int bv[3]={1,3,4};int cv[2]={2,6};for(i=0;i<3;i=i+1){a[i].val=av[i];a[i].next=i<2?&a[i+1]:0;b[i].val=bv[i];b[i].next=i<2?&b[i+1]:0;}for(i=0;i<2;i=i+1){c[i].val=cv[i];c[i].next=i<1?&c[i+1]:0;}lists[0]=a;lists[1]=b;lists[2]=c;r=merge_k_lists(lists,3);for(i=0;i<8;i=i+1){if(r==0||r->val!=e[i])return 1;r=r->next;}return 42;}
